-- Insert Quiz Questions for Lesson: Why Events Matter

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'why-events-matter' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson why-events-matter not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the primary purpose of hosting a business event?', 
    '["To entertain attendees with fun activities","To generate leads, demonstrate expertise, and begin sales conversations","To replace your website as a marketing tool","To collect as many email addresses as possible"]'::jsonb,
    'To generate leads, demonstrate expertise, and begin sales conversations',
    'Events help you generate new contacts, demonstrate your expertise, and begin sales conversations — all with a clear business purpose.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which track would be most appropriate for a consultant who wants to book training engagements?', 
    '["Speaker Track (A)","Coach Track (B)","Consultant or Trainer Track (C)","Small Business Owner Track (D)"]'::jsonb,
    'Consultant or Trainer Track (C)',
    'The Consultant or Trainer Track (C) is designed for training webinars or paid workshops that lead to proposals, consultations, or paid training enrolments.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you define before creating your event?', 
    '["The exact date and time only","Your event title, audience, value, one next step, and one success measure","The color scheme of your event page","Your social media posting schedule"]'::jsonb,
    'Your event title, audience, value, one next step, and one success measure',
    'Before creating an event, you need a clear plan: title, audience, value proposition, desired next step, and how you will measure success.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
