-- Insert Quiz Questions for Lesson: Find Events and Choose a Registration Type

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'find-events-choose-registration-type' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson find-events-choose-registration-type not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you find the Events feature in LeadProspectrr?', 
    '["Settings → Calendar","Marketing → Campaigns","Memberships → Events","Contacts → Appointments"]'::jsonb,
    'Memberships → Events',
    'The Events feature is located under Memberships → Events in the left sidebar of your sub-account.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the key difference between RSVP and Ticketed events?', 
    '["RSVP events are always in-person; Ticketed events are always online","RSVP is a free attendance-confirmation flow; Ticketed uses ticket types and checkout including free or paid tickets","RSVP events can have unlimited attendees; Ticketed events are limited to 100","RSVP events send reminders; Ticketed events do not"]'::jsonb,
    'RSVP is a free attendance-confirmation flow; Ticketed uses ticket types and checkout including free or paid tickets',
    'RSVP is for free attendance confirmation. Ticketed uses a checkout flow that supports both free and paid ticket types.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Can you switch an event from RSVP to Ticketed after creation?', 
    '["Yes, at any time before the event starts","Yes, but only if no one has registered yet","No, the registration type is fixed once created","Yes, but only with admin approval"]'::jsonb,
    'No, the registration type is fixed once created',
    'HighLevel does not allow switching between RSVP and Ticketed after event creation. You must choose correctly at the start.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
