      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Write your event name, summary, and description</p>
          <p class="text-slate-600 text-sm">Keep summary under 160 characters. Description should explain audience, benefits, and what happens next.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Set date, time, timezone, and location type</p>
          <p class="text-slate-600 text-sm">Use America/Chicago for Central Time. Choose Online or In-Person.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Add organiser details and save as Draft</p>
          <p class="text-slate-600 text-sm">Name and email are required. Add image, website, and phone for credibility. Save — it stays in Draft until published.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Build the Event Details',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Build the Event Details';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Build the Event Details

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-event-details' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-event-details not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the maximum length for an event summary?', 
    '["50 characters","100 characters","160 characters","280 characters"]'::jsonb,
    '160 characters',
    'The event summary has a maximum length of 160 characters. Keep it concise and compelling.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What timezone should you use for the clinic example?', 
    '["America/New_York (Eastern)","America/Los_Angeles (Pacific)","America/Chicago (Central)","UTC"]'::jsonb,
    'America/Chicago (Central)',
    'The clinic uses America/Chicago (Central Time). Always set the correct timezone for your audience.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When does a Draft event become publicly accessible?', 
    '["Immediately after saving","Only after you select Publish event","After 24 hours in draft","When the first person registers"]'::jsonb,
    'Only after you select Publish event',
    'A Draft event is not publicly visible. You must select Publish event to make it accessible to the public.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
